-- D1 is now the common runtime home. Populate working inventory from any active D1 tool/supply
-- catalog rows that do not already have an active inventory identity. This is database-side and
-- avoids the expensive Worker-wide legacy sync previously required.
INSERT INTO site_item_inventory (
  source_type, external_key, item_name, category, source_url, amazon_url, image_url,
  on_hand_quantity, reserved_quantity, incoming_quantity, reorder_level, unit_cost_cents,
  stock_unit_label, usage_unit_label, usage_units_per_stock_unit,
  supplier_name, supplier_sku, supplier_contact, reorder_notes, preferred_reorder_quantity,
  is_on_reorder_list, do_not_reorder, do_not_reuse, reuse_status, reservation_notes,
  is_active, last_counted_at, created_at, updated_at
)
SELECT
  LOWER(TRIM(ci.item_kind)), ci.source_key, ci.name, LOWER(TRIM(COALESCE(ci.category,''))),
  ci.amazon_url, ci.amazon_url, ci.image_url,
  COALESCE(ci.quantity_on_hand,0), 0, 0, COALESCE(ci.reorder_point,0), 0,
  'unit', 'unit', 1,
  NULL, NULL, NULL,
  CASE WHEN COALESCE(ci.source_json_path,'')<>'' THEN 'Imported from legacy catalog into D1 by Build 244; review unit breakdown and classification.' ELSE NULL END,
  0, 0, 0, 0,
  CASE WHEN ci.item_kind='tool' THEN 'reusable' ELSE 'review_required' END,
  NULL, 1, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM catalog_items ci
WHERE ci.item_kind IN ('tool','supply')
  AND COALESCE(ci.status,'active')<>'archived'
  AND NOT EXISTS (
    SELECT 1 FROM site_item_inventory sii
    WHERE LOWER(TRIM(COALESCE(sii.source_type,'')))=LOWER(TRIM(ci.item_kind))
      AND sii.external_key=ci.source_key
  );

-- Existing profile settings are never overwritten. Legacy rows without a reviewed usage profile
-- default conservatively: tools are reusable; supplies log usage without depleting an entire
-- container until stock/usage conversion has been reviewed.
INSERT INTO site_inventory_usage_profiles (
  site_item_inventory_id, usage_tracking_mode, minimum_usage_increment, notes,
  updated_by_user_id, created_at, updated_at
)
SELECT sii.site_item_inventory_id,
       CASE WHEN LOWER(TRIM(sii.source_type))='tool' THEN 'reusable' ELSE 'log_only' END,
       0.001,
       CASE WHEN LOWER(TRIM(sii.source_type))='tool'
            THEN 'Build 244 legacy/default profile: reusable tool; review if this is actually consumable.'
            ELSE 'Build 244 legacy/default profile: log use without depletion until stock/usage unit conversion is reviewed.' END,
       NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM site_item_inventory sii
WHERE COALESCE(sii.is_active,1)=1
  AND LOWER(TRIM(COALESCE(sii.source_type,''))) IN ('tool','supply')
  AND NOT EXISTS (
    SELECT 1 FROM site_inventory_usage_profiles siup
    WHERE siup.site_item_inventory_id=sii.site_item_inventory_id
  );

