  ('/custom-soap-making-ontario','custom-soap-making-ontario.text.h1.body','Custom Soap Making / Text after Custom soap making in Southern Ontario','text','[data-content-slot="custom-soap-making-ontario.text.h1.body"]','textContent','Request handmade soap ideas for gifts, baskets, markets, holiday sets, or themed custom work. We review colours, scent direction, labels, ingredients, timing, pickup or shipping, and whether the request is a good fit for our small workshop.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/custom-soap-making-ontario','custom-soap-making-ontario.text.heading.2','Custom Soap Making / Heading: Gift soap sets','text','[data-content-slot="custom-soap-making-ontario.text.heading.2"]','textContent','Gift soap sets',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/custom-soap-making-ontario','custom-soap-making-ontario.text.heading.2.body','Custom Soap Making / Text after Gift soap sets','text','[data-content-slot="custom-soap-making-ontario.text.heading.2.body"]','textContent','Personalized labels, colour themes, simple packaging notes, and gift-basket ideas can be planned before quoting.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/custom-soap-making-ontario','custom-soap-making-ontario.text.heading.3','Custom Soap Making / Heading: Small-batch planning','text','[data-content-slot="custom-soap-making-ontario.text.heading.3"]','textContent','Small-batch planning',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
  ('/custom-soap-making-ontario','custom-soap-making-ontario.text.heading.3.body','Custom Soap Making / Text after Small-batch planning','text','[data-content-slot="custom-soap-making-ontario.text.heading.3.body"]','textContent','We keep this review-first so soap requests can be matched to safe ingredients, realistic timing, and our workshop capacity.',NULL,0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
