('/social-connections','social-connections.text.heading.2','Social Connection Disclosure / Heading: What connecting means','text','[data-content-slot="social-connections.text.heading.2"]','textContent','What connecting means','',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('/social-connections','social-connections.text.heading.2.body','Social Connection Disclosure / Text after What connecting means','text','[data-content-slot="social-connections.text.heading.2.body"]','textContent','A connected platform authorizes Devil n Dove to perform only the scopes approved on the platform''s consent screen. We do not receive the social account password. Connections are used for Devil n Dove-owned Pages, professional accounts, boards, profiles, or channels.','',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('/social-connections','social-connections.text.heading.3','Social Connection Disclosure / Heading: Review-first publishing','text','[data-content-slot="social-connections.text.heading.3"]','textContent','Review-first publishing','',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('/social-connections','social-connections.text.heading.3.body','Social Connection Disclosure / Text after Review-first publishing','text','[data-content-slot="social-connections.text.heading.3.body"]','textContent','Eligible products may create internal draft packages, but drafts remain unpublished until reviewed. Media rights, privacy, product facts, destination, caption, links, and platform status must be checked before publishing.','',0,1,NULL,NULL,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
